const fs=require('node:fs');const path=require('node:path');const {ts}=require('./register.cjs');const {render,esc}=require('./serialize.cjs');
const {Shell}=require('../components/chrome.tsx');const {View,routeTitle}=require('../components/views.tsx');const {siteRoutes}=require('../lib/content.ts');
const root=path.resolve(__dirname,'..'),out=path.join(root,'preview');fs.mkdirSync(out,{recursive:true});
const css=['site.css','improvements.css'].map(name=>fs.readFileSync(path.join(root,'app',name),'utf8')).join('\n');
function moduleCode(name){return ts.transpileModule(fs.readFileSync(path.join(root,'lib/'+name+'.ts'),'utf8'),{fileName:name+'.ts',compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2020}}).outputText}
const bundle=`(()=>{const factories={${['search','reading','dom','chrome-ui','search-ui','filter-ui','reading-ui','brief-ui','interactions'].map(name=>JSON.stringify(name)+':function(require,module,exports){\n'+moduleCode(name)+'\n}').join(',')}};const cache={};function load(name){if(name.startsWith('./'))name=name.slice(2);if(cache[name])return cache[name].exports;const m={exports:{}};cache[name]=m;factories[name](load,m,m.exports);return m.exports}window.MLAI=load('interactions');})();\n`+fs.readFileSync(path.join(root,'scripts/review-router.js'),'utf8');
const {themePrepaint:prepaint}=require('../lib/chrome-ui.ts');
const favicon='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="13" fill="#17171c"/><path d="M14 47V17l18 19 18-19v30M24 47V35m16 12V35" fill="none" stroke="white" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';
fs.writeFileSync(path.join(out,'favicon.svg'),favicon);fs.writeFileSync(path.join(root,'public/favicon.svg'),favicon);
fs.writeFileSync(path.join(out,'site.css'),css);fs.writeFileSync(path.join(out,'review.js'),bundle);
function head(title,single){return `<!doctype html><html lang="en"${single?' data-single-file="true"':''}><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>${esc(title)}</title><meta name="description" content="Explore MLAI projects, source-based documentation, and evidence boundaries. Independent website review, not a production deployment."><script>${prepaint}</script>${single?'<style>'+css+'</style>':'<link rel="stylesheet" href="/site.css"><link rel="icon" href="/favicon.svg" type="image/svg+xml">'}</head><body>`}
const routes=[...siteRoutes,'/404/'];let templates='';
for(const route of routes){const view=View({route}),body=render(Shell({children:view,route}));const html=head(routeTitle(route),false)+body+'<script src="/review.js" defer></script></body></html>';const target=route==='/404/'?path.join(out,'404.html'):path.join(out,route.slice(1),'index.html');fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,html);templates+=`<template data-route="${esc(route)}" data-title="${esc(routeTitle(route))}">${render(view)}</template>`}
const single=head(routeTitle('/'),true)+render(Shell({children:View({route:'/'}),route:'/'}))+templates+'<script>'+bundle.replace(/<\/script/gi,'<\\/script')+'</script></body></html>';
fs.writeFileSync(path.join(root,'MLAI-preview.html'),single);
console.log(`Rendered ${routes.length} independent review pages; single-file review ${(Buffer.byteLength(single)/1024).toFixed(0)} KB. This is not a Next.js or React build.`);
